  "지금 저장된 {name} 내용을 그대로 고정해 둬요. 나중에 고쳐도 저장한 버전은 바뀌지 않고, 지원 기록에 제출본으로 연결할 수 있어요. 저장하지 않은 수정은 버전에 들어가지 않아요.": "Freezes the saved {name} as it is now. Later edits don't change a saved version, and you can attach it to an application as the submitted copy. Unsaved edits are not included.",
  "버전 이름(선택)": "Version name (optional)",
  "예: 가나다 제출용": "e.g. For Company A",
  "바뀐 점(선택)": "What changed (optional)",
  "예: 성과 문장 수정": "e.g. Reworded results",
  "지금 내용으로 버전 저장": "Save current content as a version",
  "지원 {n}건에 제출본으로 연결돼 지울 수 없어요": "Attached to applications as the submitted copy ({n}), so it can't be deleted",
  "{name} 열기": "Open {name}",
  "{name} 지우기": "Delete {name}",
  "지우기": "Delete",
  "아직 저장한 버전이 없어요.": "No saved versions yet.",
  "기준 버전": "Base version",
  "비교할 버전": "Version to compare",
  "비교하기": "Compare",
  "‘{title}’ 프로젝트를 삭제할까요?": "Delete the project \"{title}\"?",
  "‘{title}’ 항목을 삭제할까요?": "Delete the item \"{title}\"?",
  "내보냈어요. 열람 기록에 남았습니다.": "Exported. It was added to the access log.",
  "경력 · 이력 · 포트폴리오": "Career · Resume · Portfolio",
  "경력 · 이력 · 포트폴리오 사용법": "How to use Career · Resume · Portfolio",
  "프로젝트 기록을 경력기술서·이력서·포트폴리오로 정리하고, 필요할 때 PDF나 Word로 내보내는 화면이에요. 모든 내용은 기본이 나만 보기입니다.": "Organize project records into a career description, resume and portfolio, and export them to PDF or Word when you need to. Everything is visible only to you by default.",
  "경력기술서 탭에서 프로젝트별 성과를 확인하고 ‘문장 만들기’로 초안을 뽑아요.": "On the Career description tab, review results by project and use 'Draft sentences' to get a draft.",
  "이력서 탭에서 기본 정보와 보유 기술을 채워요.": "On the Resume tab, fill in your basic information and skills.",
  "포트폴리오 탭에서 공개 범위를 정하고, 링크 공개할 항목만 골라요.": "On the Portfolio tab, set the visibility and pick only the items to share by link.",
  "오른쪽 위 PDF/Word 버튼으로 지금 보고 있는 탭을 문서로 내보내요.": "Use the PDF/Word buttons at the top right to export the current tab as a document.",
  "나만 보기": "Only me",
  "어디에도 공개되지 않는 기본 상태예요. 커뮤니티·랭킹·검색 어디에도 나오지 않아요.": "The default. Nothing is shared, and it never appears in the community, rankings or search.",
  "링크가 있는 사람": "Anyone with the link",
  "포트폴리오에만 쓸 수 있는 옵션으로, 링크를 받은 사람이 고른 항목만 볼 수 있어요.": "Available for the portfolio only. People who get the link can see only the items you picked.",
  "워터마크": "Watermark",
  "내보낸 문서 하단에 작성자와 날짜를 남겨 유출 경로를 추적할 수 있게 해요.": "Adds the author and date at the bottom of exported documents so you can trace leaks.",
  "회사명 가리기를 켜면 내보낸 문서에도 회사명이 •로 나가요.": "With company names hidden, exported documents also show company names as •.",
  "내보내기는 열람 기록에 남아 나중에 확인할 수 있어요.": "Exports are recorded in the access log so you can check them later.",
  "비공개 · 타 사용자 노출 없음": "Private · Not shown to other users",
  "PDF 내보내기": "Export PDF",
  "Word 내보내기": "Export Word",
  "지금 보이는 경력·이력서·포트폴리오는 예시예요. 로그인하면 계정에 저장하고 고칠 수 있어요.": "The experience, resume and portfolio shown here are examples. Sign in to save and edit them in your account.",
  "경력을 불러오는 중이에요.": "Loading experience.",
  "경력을 불러오지 못했어요. 연결을 확인하고 다시 시도해 주세요.": "Couldn't load experience. Check your connection and try again.",
  "아직 남긴 경력 프로젝트가 없어요. 프로젝트를 추가해 보세요.": "No career projects yet. Add a project.",
  "프로젝트 추가": "Add project",
  "기간 확인": "Check periods",
  "‘{a}’, ‘{b}’ 기간이 겹쳐요. 겸직이나 동시 프로젝트라면 그대로 두셔도 돼요.": "\"{a}\" and \"{b}\" overlap. If they were concurrent jobs or projects, you can leave them as they are.",
  "‘{after}’ 뒤 ‘{before}’ 시작까지 {days}일이 비어요.": "There are {days} days between \"{after}\" and the start of \"{before}\".",
  "시작일이 있는 경력만 비교해요. 공백은 {n}일보다 길 때만 알려요.": "Only entries with a start date are compared. Gaps are shown only when longer than {n} days.",
  "문장 만들기": "Draft sentences",
  "담당 업무: {text}": "Duties: {text}",
  "기술: {text}": "Skills: {text}",
  "프로젝트 단위로 계속 갱신할 수 있어요.": "You can keep updating it project by project.",
  "AI 문장 다듬기가 켜져 있어요.": "AI sentence polishing is on.",
  "AI 기능은 준비 중이에요. 지금은 규칙 기반으로 만들어요.": "AI features aren't available yet. Drafts are rule-based for now.",
  "AI 다듬기는 설정 > 자동화 > AI 연동에서 민감 데이터 사용에 동의해야 켜집니다.": "To turn on AI polishing, agree to sensitive data use in Settings > Automation > AI integration.",
  "이력서는 어떤 경우에도 커뮤니티·랭킹·공유 화면에 나타나지 않아요.": "Your resume never appears in the community, rankings or shared pages.",
  "이력서 저장": "Save resume",
  "이력서를 불러오지 못했어요. 새로고침한 뒤 다시 시도해 주세요.": "Couldn't load your resume. Refresh and try again.",
  "자기소개서는 로그인하면 쓰고 계정에 저장할 수 있어요. 로그인한 뒤 이 탭을 다시 열어 주세요.": "Sign in to write a cover letter and save it to your account. Open this tab again after you sign in.",
  "회사별로 고친 글은 아래 '버전'에 이름을 붙여 남기고, 지원 기록에 제출본으로 이어 두세요. 자기소개서도 커뮤니티·랭킹·공유 화면에 나타나지 않아요.": "Save each company-specific edit as a named version below and attach it to the application as the submitted copy. Cover letters never appear in the community, rankings or shared pages either.",
  "예: 기본 자기소개서": "e.g. Default cover letter",
  "제목을 넣어야 저장할 수 있어요.": "Enter a title to save.",
  "자기소개서 저장": "Save cover letter",
  "자기소개서를 불러오지 못했어요. 새로고침한 뒤 다시 시도해 주세요.": "Couldn't load your cover letter. Refresh and try again.",
  "링크 공개를 켜도, 아래에서 직접 고른 항목만 열립니다. 지금 공개중인 항목 {n}개.": "Even with link sharing on, only the items you pick below are open. Items shared now: {n}.",
