  "내보내기에 워터마크": "Watermark exports",
  "PDF·이미지로 내보낼 때 열람자 정보를 남겨요": "Adds viewer information when exporting to PDF or images",
  "업무 카테고리와 경력·이력·포트폴리오는 공유 페이로드 생성 단계에서 한 번 더 걸러져요. 설정과 무관하게 다른 사용자에게 목록조차 노출되지 않습니다.": "Work categories, experience, resume and portfolio are filtered again when share data is built. Regardless of these settings, other users can't even see the list.",
