  "예전에 적은 기간: {period}. 시작일을 넣으면 날짜 기준으로 바뀌어요.": "Period you wrote before: {period}. Add a start date to switch to dates.",
  "프로젝트와 역할을 입력해주세요.": "Enter a project and role.",
  "포트폴리오 항목 수정": "Edit portfolio item",
  "포트폴리오 항목 추가": "Add portfolio item",
  "공개 링크를 열면 아래 칸과 결과물 링크가 그대로 보여요. 회사 기밀·개인정보·비공개 저장소 내용은 적지 마세요. 근거 연결은 공개 화면에 나가지 않아요.": "If you open a share link, the fields below and deliverable links are shown as they are. Don't include company secrets, personal data or private repository content. Evidence links never appear on the public page.",
  "결과물 링크(한 줄에 하나, 최대 {n}개)": "Deliverable links (one per line, up to {n})",
  "http 또는 https 주소만 넣을 수 있어요: {links}": "Only http or https addresses are allowed: {links}",
  "결과물 링크는 {n}개까지예요.": "You can add up to {n} deliverable links.",
  "시연 주소나 결과물 문서 주소를 넣어요.": "Add demo or deliverable document addresses.",
  "근거": "Evidence",
  "이 항목의 근거가 되는 경력과 커리어 활동을 골라요. 나만 보고, 지워진 근거는 저장할 때 빠져요.": "Pick the experience and career activities behind this item. Only you see them, and deleted evidence is dropped when you save.",
