  "링크를 받은 사람만 볼 수 있어요": "Only people with the link can see it",
  "전체 공개": "Public",
  "링크를 받은 사람만 볼 수 있어요. 기간이 지나면 닫히고, 검색에 나오지 않게 해요.": "Only people with the link can see it. It closes when the period ends and is kept out of search.",
  "링크를 아는 누구나 볼 수 있고 닫을 때까지 열려 있어요. 검색에 나올 수 있어요.": "Anyone who knows the link can see it, and it stays open until you close it. It may appear in search.",
  "종료일은 시작일과 같거나 뒤여야 해요.": "The end date must be on or after the start date.",
