  "원본 {kind}": "Source {kind}",
  "아직 연결된 기록이 없어요. 할 일이나 일정에서 기록을 시작하면 여기에 보여요.": "No linked records yet. Start recording from a task or event and it appears here.",
  "밀린 계획 다시 배치하기": "Reschedule delayed plans",
  "계획 블록과 마감 시각이 있는 할 일을 밀린 만큼 뒤로 옮기는 안을 보여 드려요. 일정은 다른 사람과의 약속일 수 있어 옮기지 않아요. 고른 것만 옮겨요.": "See a proposal that pushes plan blocks and tasks with a due time back by the delay. Events may be commitments with other people, so they are not moved. Only what you pick is moved.",
