  "다른 곳에서 먼저 바뀌어 옮기지 않은 항목이 있어요. 플래너를 확인한 뒤 다시 배치해 주세요.": "Some items changed elsewhere first and weren't moved. Check the planner and reschedule again.",
  "찾을 수 없는 항목": "Item not found",
  "되돌렸어요: {n}개. 그사이 바뀐 {m}개는 되돌리지 않았어요.": "Undone: {n}. {m} changed in the meantime and weren't undone.",
  "되돌렸어요: {n}개.": "Undone: {n}.",
  "되돌리기": "Undo",
  "고른 {n}개 옮기기": "Move selected ({n})",
  "기간 이동": "Change period",
  "플래너 보기": "Planner view",
  "기본 보기": "Default view",
  "이 보기를 기본으로": "Make this the default",
  "실행률과 월별 칸은 계정 기록으로 계산해요(칸 하나가 하루). 실행률은 계획 시간 중 실제 기록이 겹친 비율이고, 계획 없는 날은 실패로 세지 않아요. 표시가 붙은 나머지 수치는 예시예요.": "Execution rate and the monthly cells come from your account records (one cell per day). Execution rate is the share of planned time that overlaps actual records, and days without plans don't count as failures. Other figures marked as samples are examples.",
