  "이 화면의 루틴 기록은 시연용 예시 데이터예요. 계정 기록으로 계산하지 않아요.": "The routine records on this page are sample data, not calculated from your account.",
  "다른 곳에서 먼저 바뀌어 최신 내용으로 바꿨어요. 확인한 뒤 다시 시도해 주세요.": "It changed elsewhere first, so it was updated to the latest version. Check it and try again.",
  "지난 날짜는 한 해에 {max}번까지 쉬는 날로 추가할 수 있어요. {year}년에 남은 횟수는 {left}번이에요.": "You can add past dates as days off up to {max} times a year. Remaining for {year}: {left}.",
  "시작일과 종료일을 선택해주세요.": "Choose a start and end date.",
  "루틴 시작일 이후 날짜만 쉬는 날로 정할 수 있어요.": "Only dates after the routine's start date can be days off.",
  "기간은 최대 {n}일까지 정할 수 있어요.": "The period can be up to {n} days.",
  "이 기간에는 예정된 회차가 없어요.": "No occurrences are scheduled in this period.",
  "이미 쉬는 날로 정한 기간이에요.": "This period is already set as days off.",
  "오늘 완료한 루틴은 쉬는 날로 정할 수 없어요. 체크를 해제한 뒤 정해주세요.": "A routine completed today can't be a day off. Uncheck it first.",
  "‘{title}’ 루틴을 삭제할까요? 연속 기록도 함께 사라져요.": "Delete the routine \"{title}\"? Its streak is deleted too.",
  "루틴 사용법": "How to use routines",
  "반복 주기와 목표를 정해두면, 오늘 해야 할 루틴만 골라 보여주고 연속 기록을 이어줘요.": "Set a repeat and a goal, and only today's routines are shown while your streak keeps going.",
  "‘+ 새 루틴’으로 이름·시간·요일·목표를 정해요.": "Use '+ New routine' to set the name, time, days and goal.",
  "오늘 탭에서 체크하면 연속 기록이 하루 올라가요.": "Checking it on the Today tab adds a day to your streak.",
  "‘쉬는 날’에서 오늘이나 휴가 기간을 정해요. 그날은 오늘 목록에서 빠지고 연속 기록이 이어져요.": "Set today or a vacation period in 'Day off'. Those days leave the Today list and your streak continues.",
  "기간 없이 멈추려면 ‘중지’를 눌러요. ‘재개’하면 다시 오늘 목록에 나와요.": "To stop without a period, select 'Pause'. Select 'Resume' to bring it back to the Today list.",
  "검색과 필터로 분류·미완료만 골라 볼 수 있어요.": "Use search and filters to see only a category or what's not done.",
  "연속 기록": "Streak",
  "빠짐없이 이어온 날수예요. 체크를 해제하면 하루 줄어들어요.": "The number of days in a row. Unchecking removes a day.",
  "쉬는 날": "Day off",
  "달성률과 연속 기록 계산에서 빼는 날이에요. 반복에 없는 날처럼 다뤄요. 오늘 이후 날짜만 정할 수 있어요.": "A day left out of the completion rate and streak, treated like a day not in the repeat. Only today or later can be set.",
  "쉬는 중": "Resting",
  "중지했거나 오늘이 쉬는 날인 루틴이에요. 오늘 목록에서 빠지고 연속 기록도 유지돼요.": "A routine that's paused or has today off. It leaves the Today list and keeps its streak.",
