  "지금은 불가": "Not possible now",
  "금융위 마이데이터 사업자 등록과 보안 심사가 선행돼야 해요. 개인 개발 단계에서는 신청 자격 자체가 없어요.": "It requires MyData business registration with the Financial Services Commission and a security review first. An individual developer isn't eligible to apply.",
  "금융결제원 이용기관 등록과 사업자 등록이 필요하고, 토큰을 다룰 백엔드가 반드시 있어야 해요. 프론트에서 직접 호출하면 키가 노출돼요.": "It requires registration with the Korea Financial Telecommunications & Clearings Institute and a business registration, and a backend to handle tokens. Calling it from the front end exposes the key.",
  "사용자가 내려받은 CSV를 브라우저에서 파싱해 등록해요. 외부로 데이터가 나가지 않아 가장 안전합니다.": "The CSV you download is parsed in the browser and added. No data goes to outside services, so it's the safest option.",
  "뱅크샐러드·편한가계부 등의 내보내기 파일을 같은 방식으로 읽어요. 포맷이 앱마다 달라 매핑 UI가 필요해요.": "Export files from apps like Banksalad or Pyeonhan Gagyebu are read the same way. Formats differ by app, so a mapping UI is needed.",
