  "등록된 업무 기록이 없어요. 연차부터 이직 준비까지 '기록 추가'로 한곳에 정리해 보세요.": "No work records yet. Keep everything from leave to job changes in one place with 'Add record'.",
  "업무 기록 수정": "Edit work record",
  "업무 기록 작성": "New work record",
  "예: 하반기 연차 / 고객사 방문": "e.g. Second-half leave / Client visit",
  "사용 연차 (휴무일 제외 직접 입력)": "Leave days used (enter manually, excluding days off)",
  "사유 · 상세 내용 · 태그 · 멘션": "Reason · details · tags · mentions",
  "나만 보는 개인 기록이에요. 승인 상태는 메모용이며 실제 결재나 연차 차감은 하지 않아요. 민감한 인사정보는 입력하지 마세요.": "A private record only you see. The approval status is just a note; no actual approval or leave deduction happens. Don't enter sensitive HR information.",
  "‘{title}’ 기록을 이 프로젝트에서 뺐어요.": "Removed \"{title}\" from this project.",
  "‘{title}’ 기록을 이 프로젝트에 넣었어요.": "Added \"{title}\" to this project.",
  "고친 초안 글을 지금 기록으로 다시 만들까요? 고친 내용은 사라져요.": "Rebuild the draft from current records? Your edits will be lost.",
  "지금 기록으로 초안을 다시 만들었어요.": "Rebuilt the draft from current records.",
  "초안을 저장했어요. 원본 기록은 바뀌지 않아요.": "Saved the draft. The source records don't change.",
  "프로젝트 업무 보고서 초안": "Project work report draft",
  "프로젝트와 기간을 고르면, 이 프로젝트에 넣은 실제 기록 시간과 WBS 진척으로 초안을 만들어요. 자동으로 보내지 않고, 초안을 고쳐도 원본 기록은 바뀌지 않아요.": "Pick a project and period to draft a report from the actual record time in this project and WBS progress. Nothing is sent automatically, and editing the draft doesn't change the source records.",
  "로그인하면 계정의 WBS와 실제 기록으로 초안을 만들 수 있어요. 지금은 아래 예시만 볼 수 있어요.": "Sign in to draft from your account's WBS and actual records. For now you can only see the example below.",
  "최상위 WBS 작업이 없어요": "No top-level WBS items",
  "끝": "End",
  "WBS에서 최상위 작업을 만들면 프로젝트로 고를 수 있어요.": "Create a top-level item in WBS to choose it as a project.",
  "끝 날짜는 시작 날짜와 같거나 뒤여야 해요.": "The end date must be on or after the start date.",
