  "이 기간의 실제 기록": "Actual records in this period",
  "체크한 기록만 이 프로젝트의 실제 시간에 들어가요. 기록 하나는 프로젝트 하나에만 넣을 수 있어요.": "Only checked records count toward this project's actual time. Each record can belong to one project.",
  "이 기간에 끝낸 실제 기록이 없어요. 플래너에서 실제 기록을 남기면 여기에 보여요.": "No finished actual records in this period. Record in the planner and they appear here.",
  "제목 없는 기록": "Untitled record",
