  "위키를 초기 상태로 되돌릴까요? 작성한 문서가 사라져요.": "Reset the wiki? The pages you wrote will be deleted.",
  "업무 위키 사용법": "How to use the work wiki",
  "반복해서 찾는 업무 지식을 문서로 쌓아두는 공간이에요. 공간(폴더)과 해시태그로 정리하고 검색해서 찾습니다.": "A place to keep work knowledge you look up again and again. Organize it with spaces (folders) and hashtags, and find it with search.",
  "왼쪽에서 공간을 고르거나 검색어를 입력해요.": "Pick a space on the left or enter a search term.",
  "문서를 클릭하면 오른쪽에 본문이 열려요.": "Select a page to open it on the right.",
  "‘하위 문서 추가’로 문서 아래에 세부 문서를 만들 수 있어요.": "Use 'Add child page' to create detail pages under a page.",
  "본문에 #태그와 @이름을 쓰면 태그 모아보기·멘션함과 연결돼요.": "#tags and @names in the body link to the tag view and mentions.",
  "온보딩·개발·운영·회의록처럼 문서를 묶는 큰 분류예요.": "A broad group for pages, like Onboarding, Development, Operations or Meeting notes.",
