  "‘{name}’ 공수 항목을 삭제할까요?": "Delete the effort item \"{name}\"?",
  "계산 · 8월": "calculation · August",
  "공수 계산 사용법": "How to use effort calculation",
  "투입 인원과 기간으로 필요한 공수를 산정하고, 실제 투입과 비교해 편차와 비용을 확인하는 화면이에요.": "Estimate the effort you need from people and period, then compare it with actual effort to check variance and cost.",
  "산정 MD = 인원 × 기간(일) × 투입률 ÷ 100    |    MM = MD ÷ 20    |    비용 = 실제 MD × 일단가": "Estimated MD = people × days × allocation ÷ 100    |    MM = MD ÷ 20    |    Cost = actual MD × daily rate",
  "‘+ 공수 항목’으로 프로젝트와 역할을 추가해요.": "Add a project and role with '+ Effort item'.",
  "인원·기간·투입률을 입력하면 산정 MD가 자동으로 계산돼요.": "Enter people, period and allocation to calculate the estimated MD automatically.",
  "실제로 투입한 MD를 적으면 편차 배지가 초과/여유로 바뀌어요.": "Enter the actual MD and the variance badge shows over or under.",
  "검토가 끝나면 ‘이번 달 확정하기’로 잠가요.": "When the review is done, lock it with 'Confirm this month'.",
  "MD (Man-Day)": "MD (Man-Day)",
  "한 사람이 하루 온전히 투입했을 때의 작업량이에요.": "The work one person does in a full day.",
  "MM (Man-Month)": "MM (Man-Month)",
  "한 사람이 한 달 투입한 작업량. 이 서비스는 월 평균 근무일 20일 기준으로 MD ÷ 20으로 계산해요.": "The work one person does in a month. This service uses 20 working days a month, so it's MD ÷ 20.",
  "투입률": "Allocation",
  "그 기간 중 이 업무에 실제로 쓴 비율이에요. 하루 4시간만 썼다면 50%예요.": "The share of that period actually spent on this work. If you spent only 4 hours a day, it's 50%.",
  "일단가": "Daily rate",
  "1 MD당 비용이에요. 역할·등급별로 다르게 넣을 수 있어요.": "The cost per MD. You can set it differently by role or level.",
  "산정 MD와 실제 MD 차이가 0.5 MD 미만이면 ‘일치’로 표시돼요.": "If estimated and actual MD differ by less than 0.5 MD, it shows 'On target'.",
  "겸업으로 두 프로젝트를 함께 했다면 투입률을 나눠 각각 등록하세요.": "If you worked on two projects at once, split the allocation and add each one.",
  "= 인원 × 기간(일) × 투입률 · 1": "= people × days × allocation · 1",
  "+ 공수 항목": "+ Effort item",
