  "산정 {planned} MD · 실제 {actual} MD · {cost}": "Estimated {planned} MD · Actual {actual} MD · {cost}",
  "투입률은 해당 기간 중 이 업무에 쓴 비율이에요. 하루 4시간만 투입했다면 50%로 입력하세요.": "Allocation is the share of the period spent on this work. If you spent only 4 hours a day, enter 50%.",
