  "추가하기": "Add",
  "문서 제목, 인수자, 포함할 업무를 모두 채워주세요.": "Fill in the document title, recipient and work to include.",
  "업무 히스토리 · 인수인계": "Work history · Handover",
  "업무 유형별 누적 시간을 모아두고, 자리를 옮기거나 휴가를 갈 때 인수인계 문서로 바로 뽑아 쓰는 화면이에요.": "Collects time by work type so you can produce a handover document right away when you change roles or go on leave.",
