  "포함 업무 {n}건 · 섹션 {s}개": "Work included: {n} · Sections: {s}",
  "PDF는 인쇄 창에서 ‘PDF로 저장’을 선택하면 돼요. Word는 .doc 파일로 바로 내려받아요.": "For PDF, choose 'Save as PDF' in the print dialog. Word downloads directly as a .doc file.",
  "PDF로 내보내기": "Export to PDF",
  "Word로 내보내기": "Export to Word",
  "‘{title}’ 작업과 하위 작업을 모두 삭제할까요?": "Delete \"{title}\" and all its child items?",
  "작업 이름을 입력해주세요.": "Enter an item name.",
  "공수는 0 이상, 진척은 0~100으로 입력해주세요.": "Enter effort of 0 or more and progress from 0 to 100.",
  "시작·종료 날짜를 확인해주세요.": "Check the start and end dates.",
  "· 작업 분해": "· Work breakdown",
  "WBS 사용법": "How to use WBS",
  "큰 일을 작은 작업으로 쪼개고, 공수와 진척이 위로 자동 합산되게 관리하는 화면이에요.": "Break big work into smaller items, with effort and progress rolled up automatically.",
  "상위 공수 = 하위 공수 합계    |    상위 진척 = Σ(하위 진척 × 하위 공수) ÷ Σ(하위 공수)": "Parent effort = sum of child effort    |    Parent progress = Σ(child progress × child effort) ÷ Σ(child effort)",
  "‘+ 최상위 작업’으로 프로젝트를 만들어요.": "Create a project with '+ Top-level item'.",
  "각 행의 ‘하위 추가’로 작업을 더 잘게 쪼개요.": "Break items down further with 'Add child' on each row.",
  "가장 아래(말단) 작업에만 공수와 담당을 입력해요.": "Enter effort and owner only on the lowest (leaf) items.",
  "상위 행의 공수·진척은 자동으로 합산되니 직접 고치지 않아도 돼요.": "Parent effort and progress roll up automatically, so you don't edit them.",
  "행 앞의 ⌄ 를 눌러 하위 작업을 접었다 펼 수 있어요.": "Select ⌄ before a row to collapse or expand its children.",
  "말단 작업": "Leaf item",
  "하위가 없는 가장 아래 작업이에요. 공수를 직접 입력할 수 있는 행이 이것뿐이에요.": "The lowest item with no children. It's the only row where you can enter effort directly.",
  "롤업(rollup)": "Rollup",
  "하위 값을 상위로 자동 합산하는 것. 공수는 단순 합, 진척은 공수 가중 평균이에요.": "Rolling child values up to the parent automatically. Effort is a simple sum; progress is an effort-weighted average.",
  "공수 가중 평균": "Effort-weighted average",
  "큰 작업이 진척에 더 크게 반영되도록 공수를 가중치로 쓰는 계산이에요.": "A calculation that weights by effort so bigger items count more toward progress.",
  "상위 행은 공수 칸이 입력란이 아니라 ‘합계’로 표시돼요.": "On parent rows, the effort cell shows a 'Total' instead of an input.",
  "작업을 삭제하면 그 아래 하위 작업도 함께 지워져요.": "Deleting an item deletes its child items too.",
  "WBS는 업무 데이터라 다른 사용자에게 공개되지 않아요.": "WBS is work data, so it isn't shown to other users.",
  "+ 최상위 작업": "+ Top-level item",
  "작업을 불러오는 중이에요.": "Loading items.",
