  "갓생 점수 계산법": "How the productive-life score works",
  "루틴·할 일·집중 시간을 가중 합산해 100점 만점으로 계산해요. 미완료를 벌점으로 깎지 않고, 해낸 만큼만 더합니다.": "Routines, tasks and focus time are weighted into a score out of 100. Unfinished work isn't penalized; only what you did is added.",
  "점수 = 루틴 달성률×40 + 할 일 완료율×35 + min(집중시간÷목표, 1)×25": "Score = routine rate×40 + task completion×35 + min(focus time÷goal, 1)×25",
