  "지원 마감·면접": "Application deadlines and interviews",
  "커리어 목표에 따라": "Based on your career goal",
  "시각이 없는 할 일은 그날 하루가 시작될 때 알려요. 지원 일정은 커리어 목표가 취업·이직 준비면 3일 전, 그 밖에는 하루 전에 알려요. 메일·메신저로 받는 마감 알림은 발송 서비스를 연결한 뒤 켤 수 있어요(준비 중).": "Tasks without a time are reminded when the day starts. Application dates are reminded 3 days before if your career goal is a job search or job change, and 1 day before otherwise. Email and messenger reminders can be turned on after a sending service is connected (coming soon).",
  "마감 알림 설정을 불러오지 못했어요.": "Couldn't load deadline reminder settings.",
