  "커리어 목표": "Career goal",
  "고른 분류에 맞는 목표만 보여요. 목표는 커리어 대시보드 순서만 바꾸고 공개 범위나 권한은 바꾸지 않아요.": "Only goals for the chosen type are shown. A goal only changes the order of the career dashboard, not visibility or permissions.",
  "메뉴 즐겨찾기와 홈 위젯도 이 구성으로 맞추기": "Also set menu favorites and home widgets to match",
  "적용하면 바뀌는 것": "What changes when applied",
  "즐겨찾기(이 순서로): {names}": "Favorites (in this order): {names}",
  "즐겨찾기 한도({max}개)를 넘어 빠지는 메뉴: {names}": "Menus left out over the favorites limit ({max}): {names}",
  "접는 메뉴 묶음: {names}. 묶음 제목을 누르면 다시 펼쳐져요.": "Menu groups to collapse: {names}. Select a group title to expand it again.",
  "홈 위젯({mode})에서 앞에 둘 위젯: {names}": "Widgets moved to the front on home ({mode}): {names}",
  "새로 켜는 위젯: {names}": "Widgets turned on: {names}",
  "숨기거나 지우는 메뉴, 끄는 위젯은 없어요. 적용한 뒤 환경설정에서 이전 구성으로 되돌릴 수 있어요.": "No menus are hidden or removed and no widgets are turned off. After applying, you can go back to the previous layout in settings.",
  "커리어 목표만 저장하고, 메뉴 즐겨찾기·묶음 접힘·홈 위젯은 지금 그대로 둬요.": "Only the career goal is saved. Menu favorites, collapsed groups and home widgets stay as they are.",
