  "메뉴 · 즐겨찾기": "Menu · Favorites",
  "자주 쓰는 메뉴를 사이드바 맨 위에 모아 둬요. 원래 자리의 메뉴는 그대로 있고, 접근 권한도 바뀌지 않아요. 설정은 이 브라우저에만 저장돼요.": "Keep the menus you use most at the top of the sidebar. Menus stay in their original place and access doesn't change. This setting is saved in this browser only.",
  "즐겨찾기": "Favorites",
  "아직 즐겨찾기가 없어요. 아래 전체 메뉴에서 고르면 사이드바 맨 위에 보여요.": "No favorites yet. Choose from all menus below to show them at the top of the sidebar.",
