  "구독 및 결제": "Subscription and payment",
  "현재 결제 제공자가 연결되지 않아 구독 신청·변경·해지를 사용할 수 없습니다.": "No payment provider is connected, so you can't subscribe, change or cancel a plan.",
  "이 화면에서는 이용권과 결제 내역을 아직 조회할 수 없습니다. 확인되지 않은 결제일·영수증·구독 상태를 표시하지 않습니다.": "Plans and payment history can't be viewed here yet. Unconfirmed payment dates, receipts and subscription status aren't shown.",
  "서버에서 제공 상태를 확인하고 있습니다.": "Checking availability on the server.",
  "서버의 기능 제공 상태를 확인했습니다. 이 화면의 결과 조회 기능은 아직 준비 중입니다.": "Availability on the server was confirmed. Viewing results on this page is still coming soon.",
