  "수동 백업과 복원": "Manual backup and restore",
  "서버에 저장된 일기·메모·디데이·가계부·회고·완료한 집중/실제 기록과 개인 첨부를 JSON 파일로 보관합니다.": "Keeps the diaries, memos, D-Days, money logs, retrospectives, finished focus and actual records, and personal attachments stored on the server in a JSON file.",
  "최대 기록 500개, 첨부 50개·합계 5 MiB, 백업 JSON 8 MiB입니다. 한도를 넘으면 일부 자료를 누락한 파일을 만들지 않습니다.": "Up to 500 records, 50 attachments totaling 5 MiB, and an 8 MiB backup JSON. Over the limit, no file with partial data is created.",
  "포함되지 않는 자료 확인": "See what isn't included",
  "브라우저 로컬·시연 자료와 진행 중인 기록.": "Browser-only and demo data, and records in progress.",
  "일정·할 일·루틴·기존 플래너 항목·업무·경력·소셜·채팅 자료.": "Events, tasks, routines, legacy planner items, work, career, social and chat data.",
  "프로필·설정·토큰·비밀키·공유 권한과 공유 그룹·만료 첨부.": "Profile, settings, tokens, secret keys, sharing permissions, sharing groups and expired attachments.",
  "자동 백업은 제공하지 않습니다. 백업 생성 시각은 서버에서 파일을 만든 시각이며 기기에 저장됐다는 확인은 아닙니다.": "Automatic backup isn't offered. The backup time is when the server created the file, not confirmation that it was saved to your device.",
  "마지막 파일 생성": "Last file created",
  "마지막 복원 완료": "Last restore completed",
  "JSON 백업 다운로드": "Download JSON backup",
  "처리 이력 다시 확인": "Check history again",
  "파일 확인 후 병합 복원": "Check a file, then merge-restore",
  "복원할 JSON 백업 파일": "JSON backup file to restore",
  "복원 미리보기": "Restore preview",
  "서버에서 확인하고 있습니다.": "Checking on the server.",
  "이미 완료한 복원 결과": "Completed restore result",
  "복원 예정 내용": "What will be restored",
  "새로 생성 {n}개 · 기존 자료 보존 {m}개. 새 ID와 현재 계정 소유권을 사용하며 공유 권한은 복원하지 않습니다.": "New: {n} · kept: {m}. New IDs and current account ownership are used, and sharing permissions aren't restored.",
  "건너뛰기": "Skip",
  "새로 생성": "Create new",
  "확인한 내용으로 병합 복원": "Merge-restore as previewed",
  "연결이 끊기면 같은 파일과 미리보기로 다시 시도할 수 있습니다. 완료한 작업은 중복 실행하지 않습니다.": "If the connection drops, you can retry with the same file and preview. Completed work isn't run twice.",
  "로그인 후 서버에 저장된 기록을 백업할 수 있습니다.": "Sign in to back up records stored on the server.",
  "다운로드를 요청했습니다. 저장된 파일을 확인하고 안전한 위치에 보관해주세요.": "Download requested. Check the saved file and keep it somewhere safe.",
  "서버 복원이 완료됐습니다. 기존 기록은 보존했습니다. 서버 조회를 지원하는 화면에서 확인할 수 있습니다.": "Server restore is complete. Existing records were kept. You can check them on pages that read from the server.",
  "백업 JSON 파일은 1바이트~8 MiB입니다.": "A backup JSON file must be 1 byte to 8 MiB.",
  "복원 전에 파일 미리보기를 확인해주세요.": "Check the file preview before restoring.",
  "복원 완료를 확인하지 못했습니다. 같은 파일로 다시 확인해주세요.": "Couldn't confirm the restore. Check again with the same file.",
  "위젯 설정": "Widget settings",
  "보충 반영 · SET-009": "Supplement · SET-009",
  "홈 화면에 표시할 위젯을 켜고, 드래그로 순서를 바꿔보세요. 크기는 홈 화면 편집 모드에서 바꿀 수 있어요.": "Turn on the widgets to show on home and drag to reorder them. You can change sizes in home edit mode.",
