  "자동화": "Automation",
  "이미 있는 기능들을 트리거→액션으로 묶어서, 켜두기만 하면 알아서 동작하게 해요.": "Combine existing features as trigger → action so they work on their own once turned on.",
  "보안을 위해 이 브라우저에 저장된 API 키를 지웠어요. 키를 발급한 서비스에서도 그 키를 폐기해 주세요.": "For security, the API key stored in this browser was deleted. Also revoke the key at the service that issued it.",
