  "자동화 규칙은 켜고 끈 상태만 이 브라우저에 남아요. 아직 이 설정으로 실제 메일·알림을 보내거나 기록을 만들지는 않아요.": "Only whether each rule is on or off is kept in this browser. These settings don't yet send real emails or notifications or create records.",
