  "API 성공률·응답 시간·오류 수·장애 기록·알림 규칙은 서버가 모으지 않아 보이지 않아요. 여러 서버를 운영하면 각 서버의 값이 다를 수 있어요.": "API success rate, response time, error counts, incident records and alert rules aren't collected by the server, so they aren't shown. With several servers, each may show different values.",
