  "‘{name}’ 콘텐츠를 삭제할까요?": "Delete the content '{name}'?",
  "명언·플래너 템플릿·스티커팩을 서버에 저장하고 공개 여부를 정해요": "Save quotes, planner templates and sticker packs on the server and choose whether they're public",
  "+ 콘텐츠 추가": "+ Add content",
  "\"공개\"로 바꾸면 로그인한 사용자에게 보여요. 명언은 홈의 \"오늘의 문장\"에 날짜마다 하나씩, 플래너 템플릿은 템플릿 관리의 \"공용 템플릿\"에 보여요. 플래너 템플릿 내용은 한 줄에 하나씩 \"07:00 아침 스트레칭\"처럼 적어 주세요. 스티커팩은 그림 자료가 준비되면 연결해서, 지금은 사용자에게 보이지 않아요.": "Set to \"Public\" to show it to signed-in users. Quotes appear one per day in \"Today's quote\" on home, and planner templates appear in \"Shared templates\" in template management. Write planner template content one item per line, like \"07:00 Morning stretch\". Sticker packs will be connected once artwork is ready, so they aren't shown to users yet.",
